def is_sorted(lst):
    # Count occurrences of each element in the list
    count = {}
    for num in lst:
        if num in count:
            count[num] += 1
        else:
            count[num] = 1

    # Check if the list is sorted in non-decreasing order
    for i in range(1, len(lst)):
