def order_by_points(nums):
    # Define a helper function to calculate the sum of digits of a number
    def digit_sum(n):
        if n < 0:
            return -int(str(n)[1]) + sum(int(digit) for digit in str(n)[2:])
        else:
            return sum(int(digit) for digit in str(n))

    # Sort the list using the digit_sum as the key
    nums.sort(key=digit_sum)
    return nums
